}

func TestPOP3BodyLimit(t *testing.T) {
 for _, top := range []bool{false,true} {
  for _, tc := range []struct{name, wire, want string; limit int64; reject, stall bool}{
   {name:"normal", wire:"hello'"\\r\\n\\r\\n..dot\\r\\n.\\r\\n\", want:\"hello\\r\\n\\r\\n.dot\\r\\n\", limit:100},
   {name:\"exact\", wire:\"..x\\r\\n\\r\\n.\\r\\n\", want:\".x\\r\\n\\r\\n\", limit:6},
   {name:\"over\", wire:\"..x\\r\\n\\r\\n.\\r\\n\", limit:5, reject:true},
   {name:\"unlimited\", wire:strings.Repeat(\"x\",8192)+\"\\r\\n.\\r\\n\", want:strings.Repeat(\"x\",8192)+\"\\r\\n\"},
   {name:\"long-line\", wire:strings.Repeat(\"x\",128), limit:32, reject:true, stall:true},
   {name:\"empty\", wire:\".\\r\\n\", limit:1},
   {name:\"crlf-counts\", wire:\"x\\r\\n.\\r\\n\", limit:2, reject:true},
   {name:\"bare-lf\", wire:\"x\\n..y\\n.\\n\", want:\"x\\r\\n.y\\r\\n\", limit:7},
  } {
   t.Run(fmt.Sprintf(\"top=%v/%s\",top,tc.name),func(t *testing.T) {
    port, closed := bodyServer(t,tc.wire,tc.stall)
    sess, err := (Dialer{}).Dial(context.Background(),domain.POP3DialOptions{Host:\"127.0.0.1\",Port:port,Security:domain.SecurityNone,CommandTimeoutSec:3,MaxMessageBytes:tc.limit})
    if err "'!= nil { t.Fatal(err) }
    defer sess.Close()
    start := time.Now()
    var rc io.ReadCloser
    if top { rc,err = sess.Top(context.Background(),1,0) } else { rc,err = sess.Retrieve(context.Background(),1) }
    if tc.reject {
     if err == nil || !strings.Contains(err.Error(),"exceeds") || !strings.Contains(err.Error(),fmt.Sprint(tc.limit)) { t.Fatalf("want size error, got %v",err) }
     if rc != nil { t.Fatal("partial body returned") }
     if time.Since(start) >= 2*time.Second { t.Fatal("size rejection waited for command timeout") }
     select { case err := <-closed: if err != io.EOF { t.Fatalf("server did not observe EOF: %v",err) }; case <-time.After(time.Second): t.Fatal("connection not closed") }
     return
    }
    if err != nil { t.Fatal(err) }
    raw,err := io.ReadAll(rc)
    _ = rc.Close()
    if err != nil || string(raw) != tc.want { t.Fatalf("body mismatch: %q, %v",raw,err) }
    if err := sess.Delete(context.Background(),1); err != nil { t.Fatal(err) }
    if err := sess.Quit(context.Background()); err != nil { t.Fatal(err) }
   })
  }
 }
}
